// Minimal marked.js implementation for testing
if (typeof marked === 'undefined') {
  window.marked = {
    parse: function(markdown) {
      // Simple markdown to HTML conversion
      let html = markdown;
      
      // Headers
      html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
      html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
      html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');
      
      // Bold
      html = html.replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>');
      
      // Italic
      html = html.replace(/\*(.*?)\*/gim, '<em>$1</em>');
      
      // Code blocks
      html = html.replace(/```(\w+)?\n([\s\S]*?)```/gim, '<pre><code>$2</code></pre>');
      
      // Inline code
      html = html.replace(/`([^`]+)`/gim, '<code>$1</code>');
      
      // Links
      html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/gim, '<a href="$2">$1</a>');
      
      // Lists - group consecutive list items
      html = html.replace(/^(\d+\. .*$(\n\d+\. .*$)*)/gim, function(match) {
        const items = match.split('\n').map(line => line.replace(/^\d+\. (.*)$/, '<li>$1</li>')).join('\n');
        return '<ol>\n' + items + '\n</ol>';
      });
      
      html = html.replace(/^(\- .*$(\n\- .*$)*)/gim, function(match) {
        const items = match.split('\n').map(line => line.replace(/^\- (.*)$/, '<li>$1</li>')).join('\n');
        return '<ul>\n' + items + '\n</ul>';
      });
      
      // Horizontal rule
      html = html.replace(/^---$/gim, '<hr>');
      
      // Paragraphs
      html = html.split('\n\n').map(para => {
        if (!para.match(/^<[hupol]/)) {
          return '<p>' + para + '</p>';
        }
        return para;
      }).join('\n');
      
      return html;
    }
  };
}
